import{_ as o,a0 as s,w as u,s as p,ao as r,I as a,a1 as n,A as e,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"為什麼黑客更喜歡使用 Kali Linux？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼黑客更喜歡使用 Kali Linux？ | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼黑客更喜歡使用 Kali Linux？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼黑客更喜歡使用 Kali Linux？ | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230628.1 ⭐️⭐️ Why is Kali Linux Preferred by Hackers","title":"為什麼黑客更喜歡使用 Kali Linux？","tag":"202307","desc":""},"relativePath":"202307/20230628.1 ⭐️⭐️ Why is Kali Linux Preferred by Hackers.md","filePath":"[post].md"}'),d={name:"202307/20230628.1 ⭐️⭐️ Why is Kali Linux Preferred by Hackers.md"};function x(h,l,L,g,m,b){const t=s("Link");return u(),p("div",null,[l[19]||(l[19]=r('<h1 id="為什麼黑客更喜歡使用-kali-linux" tabindex="-1">為什麼黑客更喜歡使用 Kali Linux？ <a class="header-anchor" href="#為什麼黑客更喜歡使用-kali-linux" aria-label="Permalink to “為什麼黑客更喜歡使用 Kali Linux？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/04/151945ol68v2ez28e6exzq.jpg" alt=""></p><blockquote><p>以下是為什麼大多數黑客和滲透測試人員喜歡使用 Kali Linux 的幾個原因。</p></blockquote><p>Kali Linux 是一個基於 Debian “測試版” 的 Linux 操作系統，創建於近十年前。在過去幾年裏，它在黑客和網絡安全專業人員中非常流行。隨着對數字基礎設施的越來越多的依賴和網絡威脅的不斷增長，網絡安全對於普通用户和企業來説變得更加重要。</p><p>道德黑客和滲透測試人員在識別漏洞和加強系統安全方面發揮着重要作用。由於 Kali Linux 具備為安全測試和分析而量身定製的全面工具和功能，因此成為他們的首選操作系統。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Kali-Linux-with-Xfce-Desktop-Environment.jpg" alt="帶有 Xfce 桌面環境的 Kali Linux"></p><h3 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to “概述”">​</a></h3>',7)),a("p",null,[n(t,{href:"https://www.kali.org/"},{default:e(()=>[...l[0]||(l[0]=[i("Kali Linux",-1)])]),_:1}),l[1]||(l[1]=i(" 由 Offensive Security（一家美國信息安全公司）維護，並得到社區中數千名貢獻者的支持。它跟隨 Debian 的 “測試版” 分支的發展，保持與最新軟件包的同步，為黑客們提供了最新模組來進行工作。",-1))]),l[20]||(l[20]=r('<p>此外，Kali Linux 支持多種架構，例如 x86、x86-64、armel 和 armhf，這有助於黑客在廣泛的硬件範圍內使用。</p><p>使用此發行版的最大優勢之一是它適用於多個技術平台，你可以下載和使用。以下是其中一些平台：</p><ul><li>32 位和 64 位的安裝鏡像（ISO）</li><li>預構建的虛擬機鏡像</li><li>ARM 架構鏡像</li><li>用於移動設備的安卓鏡像</li><li>Docker 和 LXD 鏡像</li><li>可在各個廠商提供的雲中使用</li><li>只讀的 LIVE ISO 鏡像</li><li>可在 Windows 的 Linux 子系統（WSL）上使用</li></ul><h3 id="為何它備受青睞" tabindex="-1">為何它備受青睞 <a class="header-anchor" href="#為何它備受青睞" aria-label="Permalink to “為何它備受青睞”">​</a></h3><h4 id="強大的滲透測試工具" tabindex="-1">強大的滲透測試工具 <a class="header-anchor" href="#強大的滲透測試工具" aria-label="Permalink to “強大的滲透測試工具”">​</a></h4><p>Kali Linux 提供了豐富的滲透測試工具，使黑客能夠識別並利用漏洞。這些工具包括網絡掃描器、密碼破解器、無線攻擊框架和 Web 應用程序評估工具。這個操作系統內置瞭如此之多的工具，極大地簡化了黑客的工作流程，使他們能夠有效專注於目標。</p><h4 id="全面的安全評估" tabindex="-1">全面的安全評估 <a class="header-anchor" href="#全面的安全評估" aria-label="Permalink to “全面的安全評估”">​</a></h4><p>使用這個發行版，黑客可以對各種目標進行全面的安全評估。他們可以模擬真實攻擊，分析系統弱點，制定有效的安全策略。該操作系統提供了漏洞掃描、網絡映射和系統指紋識別等工具，使黑客能夠從不同角度評估目標系統的安全狀況。</p><h4 id="反取證分析和事件響應" tabindex="-1">反取證分析和事件響應 <a class="header-anchor" href="#反取證分析和事件響應" aria-label="Permalink to “反取證分析和事件響應”">​</a></h4><p>Kali Linux 還包括用於數字取證和事件響應的工具。黑客可以利用這些工具來調查安全漏洞，收集證據和分析受損系統。該操作系統支持數據恢復、內存分析和網絡取證，有助於進行徹底的調查，並幫助恢復遭受損害的系統。</p><h4 id="無線網絡審計" tabindex="-1">無線網絡審計 <a class="header-anchor" href="#無線網絡審計" aria-label="Permalink to “無線網絡審計”">​</a></h4><p>由於其固有的弱點，無線網絡往往是黑客的主要目標。Kali Linux 提供了全面的用於審計和保護無線網絡的工具。黑客可以使用這些工具來識別弱加密協議，發現隱藏網絡，並進行數據包分析以檢測惡意活動。這使得他們能夠評估無線網絡的安全性並提出緩解策略。</p><h3 id="大量的工具" tabindex="-1">大量的工具 <a class="header-anchor" href="#大量的工具" aria-label="Permalink to “大量的工具”">​</a></h3><p>以下是默認情況下（截至最新版本）Kali Linux 提供的一些工具類別的簡要列表：</p><ul><li><strong>信息收集</strong><ul><li>DNS 分析</li><li>IDS/IPS 識別</li><li>活動主機識別</li><li>網絡和端口掃描器</li><li>OSINT 分析</li><li>路由分析</li><li>SMB 分析</li><li>SMTP 分析</li><li>SNMP 分析</li><li>SSL 分析</li></ul></li><li><strong>漏洞分析</strong><ul><li>模糊測試工具</li><li>VoIP 工具</li></ul></li><li><strong>Web 應用程序分析</strong><ul><li>CMS 和框架識別</li><li>Web 應用程序代理</li><li>Web 爬蟲和目錄暴力破解</li><li>Web 漏洞掃描器</li></ul></li><li><strong>資料庫評估</strong><ul><li>SQLite 資料庫瀏覽器</li></ul></li><li><strong>密碼攻擊</strong><ul><li>離線攻擊工具</li><li>在線攻擊工具</li><li>哈希傳遞工具</li><li>密碼分析和密碼列表</li></ul></li><li><strong>無線網絡攻擊</strong><ul><li>802.11 無線工具</li><li>藍牙攻擊工具</li></ul></li><li><strong>逆向工程工具</strong><ul><li>Clang</li><li>NASM shell</li></ul></li><li><strong>利用工具</strong><ul><li>Metasploit</li><li>Searchsploit</li><li>MSF 載荷生成器</li><li>社會工程學工具包</li></ul></li><li><strong>嗅探和欺騙</strong><ul><li>網絡嗅探器</li><li>欺騙和中間人攻擊</li><li>後滲透</li></ul></li><li><strong>取證</strong><ul><li>反取證工具</li><li>取證鏡像工具</li><li>PDF 取證工具</li><li>Sleuth Kit 套件</li></ul></li><li><strong>報告工具</strong><ul><li>Cutycapt</li><li>Faraday start</li><li>Pipal</li></ul></li><li><strong>社會工程學工具</strong></li></ul><p>你可以在詳盡的工具門户網站瞭解更多信息：</p>',16)),a("blockquote",null,[a("p",null,[a("strong",null,[n(t,{href:"https://www.kali.org/tools/"},{default:e(()=>[...l[2]||(l[2]=[i("訪問 Kali Linux 工具門户網站",-1)])]),_:1})])])]),l[21]||(l[21]=r('<p><img src="https://www.debugpoint.com/wp-content/uploads/2023/05/Kali-Linux-Tools.jpg" alt="Kali Linux Tools"></p><h3 id="開源特性" tabindex="-1">開源特性 <a class="header-anchor" href="#開源特性" aria-label="Permalink to “開源特性”">​</a></h3><p>黑客偏愛 Kali Linux 的主要原因之一是它的開源特性。作為一款開源操作系統，Kali Linux 允許黑客訪問和修改源代碼以滿足其需求。這使得他們可以自由定製系統並添加自己的工具或功能。開源社區還積極參與開發和改進 Kali Linux，以確保其與最新的安全技術保持同步。</p><h3 id="社區支持與合作" tabindex="-1">社區支持與合作 <a class="header-anchor" href="#社區支持與合作" aria-label="Permalink to “社區支持與合作”">​</a></h3><p>Kali Linux 擁有一個龐大的安全專業人員、黑客和愛好者社區。這個社區通過分享知識、開發新工具和為其他用户提供支持來積極合作，以增強操作系統的功能。</p><p>可通過論壇、在線教程和社區驅動的文檔獲取寶貴資源並在需要時尋求幫助，確保使用 Kali Linux 的黑客能夠獲得支持。</p><p>團隊還提供了多種培訓和學習方式。其中也包括了一個學習路徑，供希望在網絡安全領域追求職業發展的學生參考，並提供相關認證。</p><h3 id="定製和靈活性" tabindex="-1">定製和靈活性 <a class="header-anchor" href="#定製和靈活性" aria-label="Permalink to “定製和靈活性”">​</a></h3><p>另一個優點是 Kali Linux 高度的定製和靈活性。黑客可以根據自己的特定需求和喜好來定製操作系統。他們可以按照自己的要求安裝和配置工具，創建自定義腳本並構建個性化的工作流程。這種定製水平使得黑客可以優化自己的生產力並簡化滲透測試過程。</p><h3 id="持續更新和改進" tabindex="-1">持續更新和改進 <a class="header-anchor" href="#持續更新和改進" aria-label="Permalink to “持續更新和改進”">​</a></h3><p>Kali Linux 是一個不斷更新和改進的操作系統。開發人員和社區成員積極致力於增強現有工具、添加新功能並解決任何安全漏洞。這些更新確保使用 Kali Linux 的黑客可以獲得最新的工具和技術，使他們始終處於網絡安全進展的前沿。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2023/06/Kali-Linux-distribute-packages-from-its-own-sources.jpg" alt="Kali Linux 從其自己的源分發軟件包"></p><h3 id="道德使用" tabindex="-1">道德使用 <a class="header-anchor" href="#道德使用" aria-label="Permalink to “道德使用”">​</a></h3><p>重要的是要注意，Kali Linux 旨在用於道德黑客和安全測試目的。道德黑客利用他們的技能來發現漏洞並保護系統，而不是從事惡意活動。</p><p>Kali Linux 倡導對黑客工具的負責和合法使用，強調獲得適當授權和遵守道德準則的重要性。該操作系統是網絡安全專業人員增強組織安全性、促進更安全的數字環境的強大工具。</p><p>簡而言之，<strong>請勿將</strong> Kali Linux 用於非法或未經授權的用途。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>我希望這份概述介紹了 Kali Linux 及其為全球安全專業人員所偏愛的免費開源操作系統的原因。它以 Debian 為基礎，配備了數千種工具和便捷的訪問方式，使它成為每個人都值得考慮的選擇。</p>',18)),a("p",null,[l[4]||(l[4]=i("你可以在 ",-1)),n(t,{href:"https://www.kali.org/get-kali/"},{default:e(()=>[...l[3]||(l[3]=[i("官方網站",-1)])]),_:1}),l[5]||(l[5]=i(" 上下載 Kali Linux。",-1))]),l[22]||(l[22]=a("p",null,[a("em",null,"（題圖：MJ/95d89a95-50fe-4fdf-a06a-e4287092cee9）")],-1)),l[23]||(l[23]=a("hr",null,null,-1)),a("p",null,[l[7]||(l[7]=i("via: ",-1)),n(t,{href:"https://www.debugpoint.com/why-kali-linux/"},{default:e(()=>[...l[6]||(l[6]=[i("https://www.debugpoint.com/why-kali-linux/",-1)])]),_:1})]),a("p",null,[l[11]||(l[11]=i("作者：",-1)),n(t,{href:"https://www.debugpoint.com/author/admin1/"},{default:e(()=>[...l[8]||(l[8]=[i("Arindam",-1)])]),_:1}),l[12]||(l[12]=i(" 選題：",-1)),n(t,{href:"https://github.com/lkxed/"},{default:e(()=>[...l[9]||(l[9]=[i("lkxed",-1)])]),_:1}),l[13]||(l[13]=i(" 譯者：ChatGPT 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:e(()=>[...l[10]||(l[10]=[i("wxy",-1)])]),_:1})]),a("p",null,[l[16]||(l[16]=i("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...l[14]||(l[14]=[i("LCTT",-1)])]),_:1}),l[17]||(l[17]=i(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:e(()=>[...l[15]||(l[15]=[i("Linux中國",-1)])]),_:1}),l[18]||(l[18]=i(" 榮譽推出",-1))])])}const w=o(d,[["render",x]]);export{T as __pageData,w as default};
